import math
a=(0.0,0.0); b=(5.0,0.3); c=(1.2,4.0)
def add(P,Q,k=1.0): return (P[0]+k*Q[0],P[1]+k*Q[1])
def sub(P,Q): return (P[0]-Q[0],P[1]-Q[1])
def dot(P,Q): return P[0]*Q[0]+P[1]*Q[1]
def dist(P,Q): return math.hypot(P[0]-Q[0],P[1]-Q[1])
def pos(P0,P1,f,fd,tau):
    d=sub(P1,P0); return add(P0,d,f(tau)),(fd(tau)*d[0],fd(tau)*d[1])
fA=lambda x:0.4+0.2*math.sin(x); fAd=lambda x:0.2*math.cos(x)
fB=lambda x:0.3+0.15*math.cos(1.3*x)+0.05*x; fBd=lambda x:-0.195*math.sin(1.3*x)+0.05
fC=lambda x:0.5+0.25*math.sin(0.7*x+1); fCd=lambda x:0.175*math.cos(0.7*x+1)
def contact(P,Pd,Q,Qd):
    d=sub(Q,P); n=(-d[1],d[0])
    lam=-dot(n,Pd)/dot(n,sub(Qd,Pd))
    return add(P,d,lam)
ok=True
for k in range(50):
    tau=0.1+0.07*k
    A,Ad=pos(b,c,fA,fAd,tau); B,Bd=pos(a,c,fB,fBd,tau); C,Cd=pos(a,b,fC,fCd,tau)
    g=contact(A,Ad,B,Bd); be=contact(A,Ad,C,Cd); al=contact(B,Bd,C,Cd)
    lhs=dist(A,g)*dist(B,al)*dist(C,be)/(dist(A,be)*dist(B,g)*dist(C,al))
    rhs=dist(a,C)*dist(b,A)*dist(c,B)/(dist(a,B)*dist(b,C)*dist(c,A))
    if abs(lhs-rhs)>1e-9*abs(rhs): ok=False; print('FAIL at',tau,lhs,rhs)
print('PASS' if ok else 'FAIL')
